#include "Core.h"
#include <iostream>
#include <set>
#include <complex>
#include <cstdlib>
int checks=0;
void check(bool ok,const char*what){++checks;if(!ok){std::cerr<<"FAIL "<<what<<'\n';std::exit(1);}}
double rms(const std::vector<float>&a){double s=0;for(float x:a)s+=x*x;return std::sqrt(s/a.size());}
int main()try{using namespace psy;
 for(double sr:{44100.,48000.,96000.,192000.})for(int wave:{0,1}){Oscillator o;int crossings=0;double prev=0;for(int i=0;i<int(sr);++i){double x=o.tick(440,sr,wave);if(x>0&&prev<=0)++crossings;prev=x;}check(std::abs(crossings-440)<=1,"oscillator 440 Hz");}
 Voice v;v.prepare(48000);v.on(36,.8);for(int i=0;i<3000;++i)v.tick();check(v.amplitude()>.79,"note on");v.on(60,.8,true);double start=v.currentPitch();for(int i=0;i<1000;++i)v.tick();check(v.currentPitch()>start&&v.currentPitch()<60,"legato gradual pitch");for(int i=0;i<48000;++i)v.tick();check(std::abs(v.currentPitch()-60)<.001,"slide octave target");v.off();for(int i=0;i<10000;++i)v.tick();check(v.amplitude()<1e-6,"note off release");
 auto f=factories();std::set<std::string> uniqueness;for(auto&p:f){auto a=render(p,48000,1);check(rms(a)>.002,"factory audible");double mean=0,peak=0,jump=0;for(size_t i=0;i<a.size();++i){check(std::isfinite(a[i]),"finite factory samples");mean+=a[i];peak=std::max(peak,std::abs(double(a[i])));if(i)jump=std::max(jump,std::abs(double(a[i]-a[i-1])));}check(peak<1,"factory clipping");check(std::abs(mean/a.size())<.005,"factory DC");check(jump<.6,"factory discontinuity");std::ostringstream sig;sig<<p.params.cutoff<<' '<<p.params.resonance;for(auto&s:p.pattern.steps)sig<<s.note<<s.active<<s.accent<<s.slide;uniqueness.insert(sig.str());}check(uniqueness.size()==32,"distinct factories");
 Preset quiet=f[0],accent=quiet;quiet.pattern.steps[0].accent=false;accent.pattern.steps[0].accent=true;quiet.pattern.length=accent.pattern.length=1;auto qa=render(quiet,48000,1,145,false),aa=render(accent,48000,1,145,false);check(rms(aa)>rms(qa)*1.05,"accent energy");
 Pattern p;p.swing=.3;for(int i=0;i<10000;++i){double ppq=i*.0073;auto pos=position(ppq,p);double pair=std::floor(ppq/(p.division*2));double rem=ppq/p.division-pair*2;int expected=(int(pair)*2+(rem>=1.3?1:0))%16;check(pos.step==expected,"swing absolute clock");}
 p.swing=0;for(int block:{32,64,128,256,512,1024}){int total=48000*2,transitions=0,last=-1;for(int base=0;base<total;base+=block)for(int i=base;i<std::min(base+block,total);++i){auto pos=position(double(i)*120/(60*48000),p);if(pos.step!=last){++transitions;last=pos.step;}}check(transitions==16,"buffer independent sequencer timing");}check(position(0,p).step==0&&position(3.9,p).step==15,"loop seek position");
 for(double sr:{44100.,48000.,88200.,96000.,176400.,192000.})for(int os:{1,2,4}){Voice s;s.params.resonance=1;s.params.drive=8;s.params.cutoff=15000;s.params.oversampling=os;s.prepare(sr);s.on(100,1,false,true);for(int i=0;i<24000;++i){s.params.cutoff=30+14970*(.5+.5*std::sin(i*.001));float x=s.tick();check(std::isfinite(x)&&std::abs(x)<1,"maximum resonance stress");}}
 auto dir=std::filesystem::temp_directory_path()/"psy303_test";std::filesystem::create_directories(dir);savePreset(dir/"test.psyfactory",f[27]);auto restored=loadPreset(dir/"test.psyfactory");check(restored.name==f[27].name&&restored.params.cutoff==f[27].params.cutoff&&restored.pattern.steps[12].note==f[27].pattern.steps[12].note,"preset roundtrip");check(render(restored,44100,1)==render(f[27],44100,1),"restored audio identical");
 midi(dir/"test.mid",f[0].pattern);std::ifstream mi(dir/"test.mid",std::ios::binary);std::string bytes((std::istreambuf_iterator<char>(mi)),{});mi.close();check(bytes.substr(0,4)=="MThd"&&uint8_t(bytes[13])==0xc0&&bytes.substr(14,4)=="MTrk","SMF header");auto audio=render(f[0],44100,1);for(int bits:{24,32})for(int ch:{1,2}){wav(dir/"test.wav",audio,44100,bits,ch);check(std::filesystem::file_size(dir/"test.wav")==44+audio.size()*size_t(ch*bits/8),"WAV size");}
 for(int i=0;i<10;++i){Kick k;k.p=kickPreset(i);k.trigger();double energy=0;for(int n=0;n<96000;++n){double x=k.tick(48000);check(std::isfinite(x)&&std::abs(x)<=1,"kick finite");energy+=x*x;}check(energy>1,"kick audible");}
 std::filesystem::remove_all(dir);std::cout<<"PASS "<<checks<<" checks: oscillator, voice, slide, accent, 32 presets, timing, stability, preset restore, MIDI, WAV, 10 kicks\n";
}catch(const std::exception&e){std::cerr<<"FAIL exception: "<<e.what()<<std::endl;return 1;}
